function taskCard(l) {
  var st = slaState(l);
  var nx = nextAction(l);
  var where = [l.property_address, l.property_size].filter(Boolean).join(' · ');
  var tel = l.phone ? String(l.phone).replace(/[^0-9+]/g, '') : '';
  var sla = slaLabel(l);
  var ownerOpts = '<option value=""' + (!l.owner ? ' selected' : '') + '>— unassigned —</option>' +
    (cfg.team || []).map(function (t) {
      return '<option value="' + esc(t.key) + '"' + (l.owner === t.key ? ' selected' : '') + '>' + esc(displayName(t.key) || t.name) + '</option>';
    }).join('');
  return '<div class="ld-task ' + st + '" role="button" tabindex="0" onclick="ldOpen(' + l.id + ')"' +
    ' onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();ldOpen(' + l.id + ')}">' +
    '<div class="ld-task-main">' +
      '<div class="tt">' + esc(prettyPerson(l.full_name) || '(no name)') + '</div>' +
      '<div class="ts"><span class="ld-pipe">' + esc(pipelinePos(l)) + '</span>' +
        (where ? '<span class="ld-sep">·</span><span>' + esc(where) + '</span>' : '') + '</div>' +
      '<div class="tm">Arrived ' + since(l.created_time || l.updated_at) +
        (sla ? ' · <span class="ld-sla ' + st + '">' + esc(sla) + '</span>' : '') + '</div>' +
      '<div class="ld-nextline">Next: <b>' + esc(nx.hint) + '</b></div>' +
    '</div>' +
    '<div class="ta">' +
      '<label class="ld-assign" onclick="event.stopPropagation()"><span>Assigned to</span>' +
        '<select class="ld-in" onchange="ldOwner(' + l.id + ', this.value)">' + ownerOpts + '</select></label>' +
      '<div class="tc">' +
        (l.phone ? '<a class="btn sm" href="tel:' + esc(tel) + '" onclick="event.stopPropagation()">Call</a>' : '') +
        (l.email ? '<a class="btn sm" href="mailto:' + esc(l.email) + '" onclick="event.stopPropagation()">Email</a>' : '') +
        (nx.stage ? '<button class="btn sm primary" onclick="event.stopPropagation();ldStage(' + l.id + ',\'' + nx.stage + '\')">' + esc(nx.done) + '</button>' : '') +
      '</div>' +
    '</div></div>';
}

