patches.find:
function prettyPerson(name) {
  var s = String(name || '').trim().replace(/\s+/g, ' ');
  if (!s) return '';
  // Meta sometimes dumps ALL CAPS or all lowercase.
  if (s === s.toUpperCase() || s === s.toLowerCase()) {
    return s.toLowerCase().replace(/(^|[\s'\-])(\S)/g, function (_, a, b) { return a + b.toUpperCase(); });
  }
  return s;
}

patches.replace:
function prettyPerson(name) {
  var s = String(name || '').replace(/[\u0000-\u001F\u007F\u2028\u2029]+/g, ' ').trim();
  // One line only — Meta/forms sometimes paste an address under the name.
  s = s.split(/\n|\r|\|/)[0].trim().replace(/\s+/g, ' ');
  if (!s) return '';
  // Meta sometimes dumps ALL CAPS or all lowercase.
  if (s === s.toUpperCase() || s === s.toLowerCase()) {
    s = s.toLowerCase().replace(/(^|[\s'\-])(\S)/g, function (_, a, b) { return a + b.toUpperCase(); });
  }
  return s;
}
